// Pure ESM, no external dependencies.
import { parseArgs } from './lib/args.mjs';
import { utf8Encode } from './lib/utf8.mjs';
import { b58encode, b58decode } from './lib/base58.mjs';
import { bytesRepr } from './lib/pyrepr.mjs';

const args = parseArgs(process.argv.slice(2));

const encoded = b58encode(utf8Encode(args.a)); // 编码字符串

let decoded;
try {
  decoded = b58decode(args.b); // 解码Base58字符串
} catch (err) {
  if (err && err.name === 'ValueError') {
    // Mirror the reference executable's unhandled-ValueError output.
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test7.py", line 10, in <module>\n');
    process.stderr.write('  File "base58/__init__.py", line 124, in b58decode\n');
    process.stderr.write('  File "base58/__init__.py", line 104, in b58decode_int\n');
    process.stderr.write(`ValueError: ${err.message}\n`);
    process.stderr.write(
      `[PYI-${process.pid}:ERROR] Failed to execute script 'test7' due to unhandled exception!\n`
    );
    process.exit(1);
  }
  throw err;
}

console.log(bytesRepr(encoded));
