全程未使用 `Buffer` / `Uint8Array` / 任何 npm 依赖，字节统一用普通 number 数组表示，纯 ESM（`import`/`export`、`.mjs` 后缀齐全）。

## 库文件

**`/output/lib/utf8.mjs`** — 手写 UTF-8 编码，对齐 Python `str.encode('utf-8')`（含代理对处理）：

```js
export function utf8Encode(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.codePointAt(i);
    if (cp > 0xffff) i++; // skip the low surrogate half
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    }
  }
  return bytes;
}
```

**`/output/lib/base58.mjs`** — base-256 ↔ base-58 逐位进位转换，前导零字节 ↔ 前导 `'1'`；非法字符抛 `ValueError`：

```js
export const BASE58_ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const ALPHABET_INDEX = new Map();
for (let i = 0; i < BASE58_ALPHABET.length; i++) ALPHABET_INDEX.set(BASE58_ALPHABET[i], i);

export function b58encode(bytes) {          // number[] -> number[] (ASCII codes)
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;
  const digits = [];
  for (let i = zeros; i < bytes.length; i++) {
    let carry = bytes[i];
    for (let j = 0; j < digits.length; j++) {
      carry += digits[j] << 8;
      digits[j] = carry % 58;
      carry = (carry / 58) | 0;
    }
    while (carry > 0) { digits.push(carry % 58); carry = (carry / 58) | 0; }
  }
  const out = [];
  for (let i = 0; i < zeros; i++) out.push(49); // '1'
  for (let i = digits.length - 1; i >= 0; i--) out.push(BASE58_ALPHABET.charCodeAt(digits[i]));
  return out;
}

export function b58decode(str) {            // string -> number[] of bytes
  let ones = 0;
  while (ones < str.length && str[ones] === '1') ones++;
  const digits = [];
  for (let i = ones; i < str.length; i++) {
    const ch = str[i];
    const value = ALPHABET_INDEX.get(ch);
    if (value === undefined) {
      const err = new Error(`Invalid character '${ch}'`);
      err.name = 'ValueError';
      throw err;
    }
    let carry = value;
    for (let j = 0; j < digits.length; j++) {
      carry += digits[j] * 58;
      digits[j] = carry & 0xff;
      carry >>= 8;
    }
    while (carry > 0) { digits.push(carry & 0xff); carry >>= 8; }
  }
  const out = [];
  for (let i = 0; i < ones; i++) out.push(0);
  for (let i = digits.length - 1; i >= 0; i--) out.push(digits[i]);
  return out;
}
```

**`/output/lib/pyrepr.mjs`** — 精确复刻 Python `repr(bytes)`：引号选择、`\t\n\r`、可打印区间、`\xNN` 小写十六进制：

```js
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) out += '\\\\';
    else if (b === quote.charCodeAt(0)) out += '\\' + quote;
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b >= 0x20 && b < 0x7f) out += String.fromCharCode(b);
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + quote;
}
```

**`/output/lib/args.mjs`** — 对齐 argparse：支持 `--a val` / `--a=val`、唯一前缀缩写、`-h/--help`（退出码 0）、缺参/多余参数/缺值均输出 usage + error 并以退出码 2 结束，prog 名取 `process.argv[1]` 的 basename（与 argparse 用 `sys.argv[0]` 一致）。核心逻辑：

```js
import { basename } from 'node:path';

const OPTIONS = ['--help', '--a', '--b'];
// usage(): `usage: ${prog} [-h] --a A --b B`
// fail(msg): usage + `PROG: error: msg` -> stderr, exit(2)

export function parseArgs(argv) {
  // 逐 token 解析 --a/--b（支持 = 内联值与唯一前缀缩写），
  // 值缺失 / 未知参数 / 缺少必填项时 fail(...) 退出码 2，
  // -h/--help 打印帮助退出码 0；成功返回 { a, b }
}
```

